43:  * @param {string} [customPath] - Optional custom path to crush.wasm
44:  * @returns {Promise<WebAssembly.Module>} Compiled WebAssembly module
45:  */
46: async function initWasm(customPath) {
47:   if (cachedWasmModule) {
48:     return cachedWasmModule;
49:   }
50: 
51:   const defaultPath = path.resolve(__dirname, 'crush.wasm');
52:   const wasmPath = customPath || defaultPath;
53: 
54:   let wasmBuffer;
