221: /**
222:  * Attempts stream resolution on a single named server node.
223:  * 
224:  * @private
225:  */
226: async function resolveSingleServer(params) {
227:   const server = params.server;
228:   const type = params.type;
229:   const tmdbId = params.tmdbId;
230:   const season = params.season;
231:   const episode = params.episode;
232:   const wasmModule = params.wasmModule;
