265: 
266:   const stream = (decrypted.data && decrypted.data.stream && decrypted.data.stream[0]) ? decrypted.data.stream[0] : null;
267:   if (!stream || !stream.playlist) {
268:     throw new Error(server + ': No playable playlist returned');
269:   }
270: 
271:   return {
272:     playlist: stream.playlist,
273:     captions: stream.captions || [],
274:     server: server,
275:     rawStream: stream
276:   };
277: }
